import {beginBottomDialogue} from './bottom-dialogue.js';
import {ULTIMATE_CINEMATIC_STEPS,cinematicSteps} from '../engine/ultimate-rules.js';
import {ULTRA_META} from './ultra-meta.js';
import {ultraPose} from '../characters/goku_ultra.js';
import {personalCaster} from '../engine/personal-ultimate.js';
export function ultraSprite(ctx,images,key,row,col,x,y,scale=1,angle=0,face=1){const im=images[key],m=ULTRA_META[key];if(!im?.complete||!im.naturalWidth||!m)return;const [w,h]=m.frameSize,[px,py]=m.pivot;ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.scale(scale*(face<0?-1:1),scale);ctx.drawImage(im,Math.max(0,Math.min(m.columns-1,col))*w,Math.max(0,Math.min(m.rows-1,row))*h,w,h,-px,-py,w,h);ctx.restore();}
export function drawUltraActor(ctx,images,d,f,hurt=false,override=null){const c=personalCaster(d,f),a=d.personalUltimate?.attack;let pose=override||ultraPose(f,hurt);if(c?.kind==='supreme')pose={row:13,frame:Math.min(2,Math.floor((d.personalUltimate.cinematic?d.personalUltimate.cinematic.elapsed/cinematicSteps(c)*3:(d.tick-c.born)/20)))};else if(a?.kind==='supreme'&&a.ownerUid===f.uid&&d.tick-a.launch<36)pose={row:d.tick-a.launch<12?12:13,frame:Math.min(5,Math.floor((d.tick-a.launch<12?d.tick-a.launch:d.tick-a.launch-12)/4))};if(f.state==='defeat')pose={row:7,frame:Math.min(5,Math.floor((d.tick-(f.deathTick??d.tick))/6))};ultraSprite(ctx,images,f.introAge!=null?'goku_ultra_intro':'goku_ultra',pose.row,pose.frame,f.x,f.y,.86,0,f.face);}
export function drawUltraBack(ctx,images,d,clock){for(const f of d.fighters)if(f.id==='goku_ultra'&&f.hp>0){if(f.introAge!=null){const age=f.introAge;ctx.save();ctx.globalAlpha=Math.min(1,age*4,(2.5-age)*4);ultraSprite(ctx,images,'goku_ultra_intro_vfx',0,Math.min(5,Math.floor(age/2.5*6)),f.x,f.y,.65);if(age>.5)ultraSprite(ctx,images,'goku_ultra_intro_vfx',1,Math.min(5,Math.floor((age-.5)/2*6)),f.x,f.y-65,.57);ctx.restore();}else if(d.tick<f.focusEnd){ctx.save();ctx.globalAlpha=.42;ultraSprite(ctx,images,'goku_ultra_vfx',3,1+Math.floor(clock*9)%5,f.x,f.y-45,.8);ctx.restore();}}}
export function drawUltraWorld(ctx,images,d){const a=d.personalUltimate?.attack;if(a?.kind==='supreme'&&a.phase==='warning'){ctx.save();ctx.strokeStyle='#d2f5ff';ctx.lineWidth=2;ctx.setLineDash([14,9]);for(const side of [-1,1]){ctx.beginPath();ctx.moveTo(a.x-a.dy*65*side,a.y+a.dx*65*side);ctx.lineTo(a.x+a.dx*1600-a.dy*65*side,a.y+a.dy*1600+a.dx*65*side);ctx.stroke();}ctx.restore();ultraSprite(ctx,images,'goku_ultra_ultimate_vfx',1,Math.min(2,Math.floor((d.tick-a.born)/12)),a.x+a.dx*45,a.y+a.dy*45-28,.75);}if(a?.kind==='supreme'&&a.phase==='travel'&&d.tick-a.launch<12)ultraSprite(ctx,images,'goku_ultra_ultimate_vfx',0,Math.min(5,Math.floor((d.tick-a.launch)/2)),a.x+a.dx*65,a.y+a.dy*65-28,.85,Math.atan2(a.dy,a.dx));for(const f of d.fighters)if(f.id==='goku_ultra'&&f.introAge!=null&&f.introAge>1.1&&f.introAge<1.8){ctx.save();ctx.globalAlpha=.6;ultraSprite(ctx,images,'goku_ultra_intro_vfx',2,Math.min(5,Math.floor((f.introAge-1.1)/.7*6)),f.x,f.y-65,.75);ctx.restore();}}
export function drawUltraShot(ctx,images,s,x,y,clock){ultraSprite(ctx,images,s.kind==='supreme'?'goku_ultra_ultimate_vfx':'goku_ultra_vfx',2,s.kind==='supreme'?Math.floor(clock*14)%6:3+Math.floor(clock*14)%2,x,y,s.kind==='supreme'?1.4:.68,Math.atan2(s.vy,s.vx));}
export function drawUltraChat(ctx,images,c,line='Kamehameha!',reduced=false){const p=c.elapsed/cinematicSteps(c);beginBottomDialogue(ctx);ctx.globalAlpha=Math.max(0,Math.min(1,p*10,(1-p)*12));const slide=reduced?0:Math.max(0,1-p*9)*65;ultraSprite(ctx,images,'goku_ultra_dialogue',0,p>.45?1:0,480+slide,310,.71);ultraSprite(ctx,images,'goku_ultra_dialogue',2,p>.5?1:0,177+slide,306,.25);ctx.textAlign='left';ctx.fillStyle='#eaf9ff';ctx.font='bold 13px Segoe UI';ctx.fillText('GOKU ULTRA INSTINCT',302+slide,275,490);ctx.font='bold 26px Georgia';ctx.fillText(line,302+slide,320,520);ctx.restore();}
export function drawUltraCinematic(ctx,images,d,reduced=false){const c=d.personalUltimate?.cinematic,a=d.personalUltimate?.attack;if((c||a)?.kind!=='supreme')return;if(c)drawUltraChat(ctx,images,c,undefined,reduced);else if(a.phase==='travel'&&d.tick-a.launch<48){ctx.save();ctx.globalAlpha=Math.min(1,(48-d.tick+a.launch)/12);ultraSprite(ctx,images,'goku_ultra_dialogue',3,0,480,92,.55);ctx.restore();}}
